def getProviderLimits(self, provider):
    # Initialize the quota with infinity
    cloud_quota = ResourceLimits(instances=float('inf'), vcpus=float('inf'), memory_gb=float('inf'))

    # Add the quota for each provider except the current one
    for other_provider in self.api.providers:
        if other_provider != provider:
            cloud_quota -= self.api.nodes_cache.getQuota(other_provider)

    # Get the provider-specific resource limits
    provider_resource_limits = self.api.nodes_cache.getProviderResourceLimits(provider)

    # Calculate the final quota by taking the minimum of cloud quota and provider resource limits
    return min(cloud_quota, provider_resource_limits)
